// ===== PURE COLOR MATH (no Compose) BEGIN =====
// Everything between BEGIN and END uses only Int ARGB values so it can be unit tested on a plain JVM.

internal object ClgColorMath {
    const val WHITE = 0xFFFFFFFF.toInt()
    const val BLACK = 0xFF000000.toInt()

    private fun ch(c: Int, shift: Int) = (c ushr shift) and 0xFF

    fun lerp(a: Int, b: Int, t: Float): Int {
        val f = t.coerceIn(0f, 1f)
        fun mix(shift: Int) = (ch(a, shift) + (ch(b, shift) - ch(a, shift)) * f + 0.5f).toInt().coerceIn(0, 255)
        return (0xFF shl 24) or (mix(16) shl 16) or (mix(8) shl 8) or mix(0)
    }

    private fun lin(v: Int): Double {
        val s = v / 255.0
        return if (s <= 0.03928) s / 12.92 else Math.pow((s + 0.055) / 1.055, 2.4)
    }

    /** WCAG relative luminance. */
    fun luminance(c: Int): Double = 0.2126 * lin(ch(c, 16)) + 0.7152 * lin(ch(c, 8)) + 0.0722 * lin(ch(c, 0))

    /** WCAG contrast ratio, 1.0 .. 21.0. */
    fun contrast(a: Int, b: Int): Double {
        val la = luminance(a); val lb = luminance(b)
        return (maxOf(la, lb) + 0.05) / (minOf(la, lb) + 0.05)
    }

    /** Black or white, whichever reads better on [bg]. */
    fun onColorFor(bg: Int): Int = if (contrast(WHITE, bg) >= contrast(BLACK, bg)) WHITE else BLACK

    /** Moves [fg] towards [towards] in small steps until it reaches [min] contrast against [bg]. */
    fun ensureContrast(fg: Int, bg: Int, min: Double, towards: Int): Int {
        var c = fg
        var step = 0
        while (contrast(c, bg) < min && step < 40) { step++; c = lerp(fg, towards, step / 40f) }
        return if (contrast(c, bg) >= min) c else towards
    }
}

/** Seeds for one palette. Light and dark schemes are derived from these. */
internal data class ClgPaletteSpec(
    val id: String, val label: String, val blurb: String,
    val primary: Int, val secondary: Int, val tertiary: Int,
    val darkBg: Int, val lightBg: Int, val amoled: Boolean = false
)

/** Every role we use, as ARGB ints. */
internal data class ClgSchemeInts(
    val dark: Boolean,
    val primary: Int, val onPrimary: Int, val primaryContainer: Int, val onPrimaryContainer: Int,
    val secondary: Int, val onSecondary: Int, val secondaryContainer: Int, val onSecondaryContainer: Int,
    val tertiary: Int, val onTertiary: Int, val tertiaryContainer: Int, val onTertiaryContainer: Int,
    val background: Int, val onBackground: Int, val surface: Int, val onSurface: Int,
    val surfaceVariant: Int, val onSurfaceVariant: Int, val outline: Int, val outlineVariant: Int,
    val error: Int, val onError: Int, val errorContainer: Int, val onErrorContainer: Int,
    val inverseSurface: Int, val inverseOnSurface: Int, val inversePrimary: Int,
    val surfaceContainerLowest: Int, val surfaceContainerLow: Int, val surfaceContainer: Int,
    val surfaceContainerHigh: Int, val surfaceContainerHighest: Int
)

internal object ClgPaletteMath {
    private val M = ClgColorMath

    fun build(spec: ClgPaletteSpec, dark: Boolean): ClgSchemeInts {
        val towardsAccent = if (dark) M.WHITE else M.BLACK         // lighten accents on dark, darken on light
        val bg = if (dark) spec.darkBg else spec.lightBg
        val surface = when {
            dark && spec.amoled -> 0xFF0A0A0A.toInt()
            dark -> M.lerp(bg, M.WHITE, 0.04f)
            else -> M.lerp(bg, M.WHITE, 0.55f)
        }
        val onBg = if (dark) M.lerp(0xFFEAEFF7.toInt(), spec.primary, 0.05f) else M.lerp(0xFF10151C.toInt(), spec.primary, 0.08f)
        val onSurface = M.ensureContrast(onBg, surface, 7.0, if (dark) M.WHITE else M.BLACK)

        fun accent(seed: Int) = M.ensureContrast(seed, surface, 4.5, towardsAccent)
        val primary = accent(spec.primary); val secondary = accent(spec.secondary); val tertiary = accent(spec.tertiary)

        fun container(a: Int) = if (dark) M.lerp(a, bg, 0.72f) else M.lerp(a, M.WHITE, 0.82f)
        fun onContainer(a: Int, c: Int) =
            if (dark) M.ensureContrast(M.lerp(a, M.WHITE, 0.75f), c, 7.0, M.WHITE)
            else M.ensureContrast(M.lerp(a, M.BLACK, 0.65f), c, 7.0, M.BLACK)
        val pc = container(primary); val sc = container(secondary); val tc = container(tertiary)

        val surfaceVariant = M.lerp(surface, primary, 0.10f)
        val onSurfaceVariant = M.ensureContrast(M.lerp(onSurface, surfaceVariant, 0.25f), surfaceVariant, 4.5, if (dark) M.WHITE else M.BLACK)
        val outline = M.ensureContrast(M.lerp(onSurface, surface, 0.45f), surface, 3.0, if (dark) M.WHITE else M.BLACK)

        val error = M.ensureContrast(if (dark) 0xFFFF8A80.toInt() else 0xFFB3261E.toInt(), surface, 4.5, towardsAccent)
        val errorContainer = if (dark) M.lerp(error, bg, 0.75f) else M.lerp(error, M.WHITE, 0.85f)

        val inverseSurface = onSurface
        val inversePrimary = M.ensureContrast(spec.primary, inverseSurface, 4.5, if (dark) M.BLACK else M.WHITE)

        fun tint(t: Float) = M.lerp(surface, primary, t)
        return ClgSchemeInts(
            dark = dark,
            primary = primary, onPrimary = M.onColorFor(primary), primaryContainer = pc, onPrimaryContainer = onContainer(primary, pc),
            secondary = secondary, onSecondary = M.onColorFor(secondary), secondaryContainer = sc, onSecondaryContainer = onContainer(secondary, sc),
            tertiary = tertiary, onTertiary = M.onColorFor(tertiary), tertiaryContainer = tc, onTertiaryContainer = onContainer(tertiary, tc),
            background = bg, onBackground = M.ensureContrast(onBg, bg, 7.0, if (dark) M.WHITE else M.BLACK), surface = surface, onSurface = onSurface,
            surfaceVariant = surfaceVariant, onSurfaceVariant = onSurfaceVariant, outline = outline, outlineVariant = M.lerp(outline, surface, 0.55f),
            error = error, onError = M.onColorFor(error), errorContainer = errorContainer, onErrorContainer = M.ensureContrast(M.lerp(error, if (dark) M.WHITE else M.BLACK, 0.7f), errorContainer, 7.0, if (dark) M.WHITE else M.BLACK),
            inverseSurface = inverseSurface, inverseOnSurface = M.ensureContrast(surface, inverseSurface, 4.5, if (dark) M.BLACK else M.WHITE), inversePrimary = inversePrimary,
            surfaceContainerLowest = if (dark && spec.amoled) M.BLACK else tint(0.0f), surfaceContainerLow = tint(0.03f), surfaceContainer = tint(0.06f),
            surfaceContainerHigh = tint(0.09f), surfaceContainerHighest = tint(0.12f)
        )
    }
}

/** The palettes a student can pick. DYNAMIC uses Material You wallpaper colours on Android 12+. */
enum class ClgPalette(val id: String, val label: String, val blurb: String) {
    BRAND("brand", "Midnight Cyan", "The Clg 1% look: deep navy with electric cyan."),
    AURORA("aurora", "Aurora", "Violet and pink glow on a deep purple night."),
    FOREST("forest", "Forest", "Calm greens, easy on the eyes for long study sessions."),
    SUNSET("sunset", "Sunset", "Warm orange and coral energy."),
    OCEAN("ocean", "Ocean", "Clear blues with a cool teal accent."),
    SAKURA("sakura", "Sakura", "Soft pink and plum, gentle and bright."),
    GRAPHITE("graphite", "Graphite", "Neutral greys. Minimal and distraction free."),
    AMOLED("amoled", "AMOLED Black", "True black in dark mode: saves battery on OLED screens."),
    PAPER("paper", "Paper", "Warm cream and brown, like a printed notebook."),
    DYNAMIC("dynamic", "Material You", "Follows your wallpaper colours (Android 12 or newer).");

    companion object {
        fun fromId(id: String?): ClgPalette = values().firstOrNull { it.id == id } ?: BRAND
    }
}

internal fun ClgPalette.spec(): ClgPaletteSpec = when (this) {
    ClgPalette.BRAND, ClgPalette.DYNAMIC -> ClgPaletteSpec(id, label, blurb, 0xFF00D9F0.toInt(), 0xFF5B8DEF.toInt(), 0xFF7CF4C5.toInt(), 0xFF010824.toInt(), 0xFFF2F8FF.toInt())
    ClgPalette.AURORA -> ClgPaletteSpec(id, label, blurb, 0xFF9B7BFF.toInt(), 0xFFFF7AC6.toInt(), 0xFF5EEAD4.toInt(), 0xFF0E0A1F.toInt(), 0xFFF7F3FF.toInt())
    ClgPalette.FOREST -> ClgPaletteSpec(id, label, blurb, 0xFF3FBF7F.toInt(), 0xFF8BC34A.toInt(), 0xFFF2C14E.toInt(), 0xFF07130D.toInt(), 0xFFF1F9F3.toInt())
    ClgPalette.SUNSET -> ClgPaletteSpec(id, label, blurb, 0xFFFF7A45.toInt(), 0xFFFFB347.toInt(), 0xFFFF5C8A.toInt(), 0xFF150B08.toInt(), 0xFFFFF6F0.toInt())
    ClgPalette.OCEAN -> ClgPaletteSpec(id, label, blurb, 0xFF3D8BFF.toInt(), 0xFF26C6DA.toInt(), 0xFF7C4DFF.toInt(), 0xFF06101F.toInt(), 0xFFF0F6FF.toInt())
    ClgPalette.SAKURA -> ClgPaletteSpec(id, label, blurb, 0xFFF06292.toInt(), 0xFFBA68C8.toInt(), 0xFFFFB74D.toInt(), 0xFF170A12.toInt(), 0xFFFFF7FA.toInt())
    ClgPalette.GRAPHITE -> ClgPaletteSpec(id, label, blurb, 0xFFB0BEC5.toInt(), 0xFF90A4AE.toInt(), 0xFFCFD8DC.toInt(), 0xFF101214.toInt(), 0xFFF5F6F7.toInt())
    ClgPalette.AMOLED -> ClgPaletteSpec(id, label, blurb, 0xFF00E5FF.toInt(), 0xFF69F0AE.toInt(), 0xFFFFD740.toInt(), 0xFF000000.toInt(), 0xFFF2F8FF.toInt(), amoled = true)
    ClgPalette.PAPER -> ClgPaletteSpec(id, label, blurb, 0xFF8D5A2B.toInt(), 0xFF6B7F3A.toInt(), 0xFFB5543A.toInt(), 0xFF14110D.toInt(), 0xFFFAF6EE.toInt())
}

// ===== PURE COLOR MATH END =====

/** Material You wallpaper colours exist from Android 12 (API 31). */
fun clgDynamicColorSupported(): Boolean = Build.VERSION.SDK_INT >= Build.VERSION_CODES.S

private fun Int.c() = Color(this)

internal fun ClgSchemeInts.toColorScheme(): ColorScheme = if (dark) darkColorScheme(
    primary = primary.c(), onPrimary = onPrimary.c(), primaryContainer = primaryContainer.c(), onPrimaryContainer = onPrimaryContainer.c(),
    secondary = secondary.c(), onSecondary = onSecondary.c(), secondaryContainer = secondaryContainer.c(), onSecondaryContainer = onSecondaryContainer.c(),
    tertiary = tertiary.c(), onTertiary = onTertiary.c(), tertiaryContainer = tertiaryContainer.c(), onTertiaryContainer = onTertiaryContainer.c(),
    background = background.c(), onBackground = onBackground.c(), surface = surface.c(), onSurface = onSurface.c(),
    surfaceVariant = surfaceVariant.c(), onSurfaceVariant = onSurfaceVariant.c(), outline = outline.c(), outlineVariant = outlineVariant.c(),
    error = error.c(), onError = onError.c(), errorContainer = errorContainer.c(), onErrorContainer = onErrorContainer.c(),
    inverseSurface = inverseSurface.c(), inverseOnSurface = inverseOnSurface.c(), inversePrimary = inversePrimary.c(),
    surfaceContainerLowest = surfaceContainerLowest.c(), surfaceContainerLow = surfaceContainerLow.c(), surfaceContainer = surfaceContainer.c(),
    surfaceContainerHigh = surfaceContainerHigh.c(), surfaceContainerHighest = surfaceContainerHighest.c()
) else lightColorScheme(
    primary = primary.c(), onPrimary = onPrimary.c(), primaryContainer = primaryContainer.c(), onPrimaryContainer = onPrimaryContainer.c(),
    secondary = secondary.c(), onSecondary = onSecondary.c(), secondaryContainer = secondaryContainer.c(), onSecondaryContainer = onSecondaryContainer.c(),
    tertiary = tertiary.c(), onTertiary = onTertiary.c(), tertiaryContainer = tertiaryContainer.c(), onTertiaryContainer = onTertiaryContainer.c(),
    background = background.c(), onBackground = onBackground.c(), surface = surface.c(), onSurface = onSurface.c(),
    surfaceVariant = surfaceVariant.c(), onSurfaceVariant = onSurfaceVariant.c(), outline = outline.c(), outlineVariant = outlineVariant.c(),
    error = error.c(), onError = onError.c(), errorContainer = errorContainer.c(), onErrorContainer = onErrorContainer.c(),
    inverseSurface = inverseSurface.c(), inverseOnSurface = inverseOnSurface.c(), inversePrimary = inversePrimary.c(),
    surfaceContainerLowest = surfaceContainerLowest.c(), surfaceContainerLow = surfaceContainerLow.c(), surfaceContainer = surfaceContainer.c(),
    surfaceContainerHigh = surfaceContainerHigh.c(), surfaceContainerHighest = surfaceContainerHighest.c()
)

/** Color scheme for a palette (not DYNAMIC; that one needs a Context, see ClgPaletteTheme). */
fun ClgPalette.colorScheme(dark: Boolean): ColorScheme = ClgPaletteMath.build(spec(), dark).toColorScheme()

/** Corner style per palette so themes feel different, not just recoloured. */
fun ClgPalette.shapes(): Shapes = when (this) {
    ClgPalette.SAKURA, ClgPalette.PAPER -> Shapes(RoundedCornerShape(10.dp), RoundedCornerShape(16.dp), RoundedCornerShape(22.dp), RoundedCornerShape(30.dp), RoundedCornerShape(38.dp))
    ClgPalette.GRAPHITE -> Shapes(RoundedCornerShape(4.dp), RoundedCornerShape(8.dp), RoundedCornerShape(12.dp), RoundedCornerShape(16.dp), RoundedCornerShape(20.dp))
    else -> Shapes(RoundedCornerShape(8.dp), RoundedCornerShape(12.dp), RoundedCornerShape(16.dp), RoundedCornerShape(24.dp), RoundedCornerShape(32.dp))
}

/**
 * Drop-in replacement for the body of MyApplicationTheme.
 * [themeMode] = your existing System / Light / Dark setting, [palette] = the colour theme.
 */
@Composable
fun ClgPaletteTheme(
    themeMode: ThemeMode,
    palette: ClgPalette,
    typography: androidx.compose.material3.Typography = MaterialTheme.typography,
    content: @Composable () -> Unit
) {
    val systemDark = isSystemInDarkTheme()
    val dark = when (themeMode) { ThemeMode.LIGHT -> false; ThemeMode.DARK -> true; ThemeMode.SYSTEM -> systemDark }
    val context = LocalContext.current
    val scheme = if (palette == ClgPalette.DYNAMIC && clgDynamicColorSupported()) {
        if (dark) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)
    } else palette.colorScheme(dark)

    val view = LocalView.current
    if (!view.isInEditMode) SideEffect {
        val window = (view.context as? Activity)?.window ?: return@SideEffect
        val controller = WindowCompat.getInsetsController(window, view)
        controller.isAppearanceLightStatusBars = !dark          // dark icons on light backgrounds
        controller.isAppearanceLightNavigationBars = !dark
    }
    MaterialTheme(colorScheme = scheme, typography = typography, shapes = palette.shapes(), content = content)
}

// ------------------------------------------------------------------------------------------------ saving

object ClgThemeStore {
    private const val PREFS = "clg1_theme"
    private const val KEY = "palette"
    fun load(context: Context): ClgPalette = ClgPalette.fromId(context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString(KEY, null))
    fun save(context: Context, palette: ClgPalette) { context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putString(KEY, palette.id).apply() }
}

/** Remembers the chosen palette and saves it. Use: val (palette, setPalette) = rememberClgPalette() */
@Composable
fun rememberClgPalette(): Pair<ClgPalette, (ClgPalette) -> Unit> {
    val context = LocalContext.current
    var palette by remember { mutableStateOf(ClgThemeStore.load(context)) }
    return palette to { p: ClgPalette -> palette = p; ClgThemeStore.save(context, p) }
}

// ------------------------------------------------------------------------------------------------ picker

/** Settings section: choose a palette and System / Light / Dark. Changes apply immediately. */
@Composable
fun ClgThemePicker(
    selected: ClgPalette, onSelect: (ClgPalette) -> Unit,
    themeMode: ThemeMode, onModeChange: (ThemeMode) -> Unit,
    modifier: Modifier = Modifier
) {
    val systemDark = isSystemInDarkTheme()
    val previewDark = when (themeMode) { ThemeMode.LIGHT -> false; ThemeMode.DARK -> true; ThemeMode.SYSTEM -> systemDark }
    val haptic = LocalHapticFeedback.current

    Column(modifier = modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Text("Appearance", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            listOf(ThemeMode.SYSTEM to "System", ThemeMode.LIGHT to "Light", ThemeMode.DARK to "Dark").forEach { (mode, label) ->
                FilterChip(selected = themeMode == mode, onClick = { onModeChange(mode) }, label = { Text(label) })
            }
        }
        ClgPalette.values().toList().chunked(2).forEach { rowItems ->
            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                rowItems.forEach { p ->
                    val enabled = p != ClgPalette.DYNAMIC || clgDynamicColorSupported()
                    PaletteCard(p, previewDark, p == selected, enabled, Modifier.weight(1f)) {
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove); onSelect(p)
                    }
                }
                if (rowItems.size == 1) Spacer(Modifier.weight(1f))
            }
        }
        if (!clgDynamicColorSupported()) Text("Material You needs Android 12 or newer.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
    }
}

@Composable
private fun PaletteCard(p: ClgPalette, dark: Boolean, isSelected: Boolean, enabled: Boolean, modifier: Modifier, onClick: () -> Unit) {
    val s = ClgPaletteMath.build(p.spec(), dark)
    val shape = RoundedCornerShape(20.dp)
    Surface(
        onClick = onClick, enabled = enabled, shape = shape,
        color = MaterialTheme.colorScheme.surfaceContainer,
        border = BorderStroke(if (isSelected) 2.dp else 1.dp, if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant),
        modifier = modifier.semantics { selected = isSelected; contentDescription = "${p.label} theme" + if (isSelected) ", selected" else if (!enabled) ", not available" else "" }
    ) {
        Column(Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            // a tiny preview of the real colours
            Box(Modifier.fillMaxWidth().height(70.dp).clip(RoundedCornerShape(14.dp)).background(Color(s.background)).padding(8.dp)) {
                Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    Box(Modifier.fillMaxWidth(0.55f).height(10.dp).clip(CircleShape).background(Color(s.primary)))
                    Box(Modifier.fillMaxWidth().height(16.dp).clip(RoundedCornerShape(6.dp)).background(Color(s.surfaceContainerHigh)))
                    Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                        Box(Modifier.size(12.dp).clip(CircleShape).background(Color(s.secondary)))
                        Box(Modifier.size(12.dp).clip(CircleShape).background(Color(s.tertiary)))
                        Box(Modifier.width(24.dp).height(12.dp).clip(CircleShape).background(Color(s.primaryContainer)))
                    }
                }
            }
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(p.label, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.SemiBold, modifier = Modifier.weight(1f), maxLines = 1)
                if (isSelected) Icon(Icons.Default.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
            }
            Text(p.blurb, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant, maxLines = 3)
        }
    }
}

/*
 * ---- Snippet: make your existing theme use the palettes (replace the body of MyApplicationTheme) ----
 *
 * @Composable
 * fun MyApplicationTheme(
 *     themeMode: ThemeMode = ThemeMode.SYSTEM,
 *     palette: ClgPalette = ClgPalette.BRAND,
 *     content: @Composable () -> Unit
 * ) {
 *     ClgPaletteTheme(themeMode = themeMode, palette = palette, typography = Typography, content = content)
 * }
 */
